import './styles.css';
import { useState, useMemo } from 'react';

// Simulated word predictions based on common patterns
// In reality, LLMs use billions of parameters - this is a simplified demo
const predictionDatabase: Record<string, Array<{ word: string; probability: number; explanation: string }>> = {
  'the capital of france is': [
    { word: 'Paris', probability: 0.95, explanation: 'Overwhelmingly the most likely - this is a well-known fact' },
    { word: 'a', probability: 0.02, explanation: 'Could continue "is a beautiful city"' },
    { word: 'located', probability: 0.015, explanation: 'Could continue "is located in..."' },
    { word: 'known', probability: 0.01, explanation: 'Could continue "is known for..."' },
  ],
  'the capital of kenya is': [
    { word: 'Nairobi', probability: 0.94, explanation: 'The correct and most likely answer' },
    { word: 'a', probability: 0.03, explanation: 'Could start a description' },
    { word: 'located', probability: 0.02, explanation: 'Geographic description' },
    { word: 'one', probability: 0.01, explanation: 'Could say "is one of..."' },
  ],
  'once upon a': [
    { word: 'time', probability: 0.98, explanation: 'Classic fairy tale opening - extremely predictable!' },
    { word: 'day', probability: 0.01, explanation: 'Less common but possible' },
    { word: 'midnight', probability: 0.005, explanation: 'Unusual but grammatically valid' },
  ],
  'the quick brown fox': [
    { word: 'jumps', probability: 0.92, explanation: 'Famous pangram - the model knows this phrase well' },
    { word: 'jumped', probability: 0.05, explanation: 'Past tense version' },
    { word: 'ran', probability: 0.02, explanation: 'Alternative action' },
    { word: 'is', probability: 0.01, explanation: 'Could describe the fox' },
  ],
  'i love to eat': [
    { word: 'pizza', probability: 0.15, explanation: 'Common food mentioned with "love to eat"' },
    { word: 'food', probability: 0.12, explanation: 'General term' },
    { word: 'breakfast', probability: 0.10, explanation: 'Meal reference' },
    { word: 'chocolate', probability: 0.08, explanation: 'Popular treat' },
  ],
  'artificial intelligence is': [
    { word: 'a', probability: 0.25, explanation: 'Starting a definition' },
    { word: 'the', probability: 0.20, explanation: 'Emphasizing importance' },
    { word: 'transforming', probability: 0.15, explanation: 'Common claim about AI' },
    { word: 'changing', probability: 0.12, explanation: 'Similar to transforming' },
  ],
  'machine learning': [
    { word: 'is', probability: 0.30, explanation: 'Starting a definition or explanation' },
    { word: 'models', probability: 0.20, explanation: 'Technical term often follows' },
    { word: 'algorithms', probability: 0.15, explanation: 'Another technical continuation' },
    { word: 'and', probability: 0.10, explanation: 'Could list "ML and AI"' },
  ],
  'to be or not to': [
    { word: 'be', probability: 0.99, explanation: 'Shakespeare quote - extremely predictable!' },
    { word: 'do', probability: 0.005, explanation: 'Grammatically possible but very unlikely' },
  ],
  'roses are red violets are': [
    { word: 'blue', probability: 0.97, explanation: 'Famous poem - the pattern is very strong' },
    { word: 'purple', probability: 0.02, explanation: 'Technically more accurate but less common' },
    { word: 'violet', probability: 0.005, explanation: 'Playing on the word' },
  ],
};

const examplePhrases = [
  'the capital of france is',
  'the capital of kenya is',
  'once upon a',
  'the quick brown fox',
  'i love to eat',
  'artificial intelligence is',
  'machine learning',
  'to be or not to',
  'roses are red violets are',
];

function ProbabilityBar({ probability, isTop }: { probability: number; isTop: boolean }) {
  return (
    <div className="probability-bar">
      <div 
        className={`probability-fill ${isTop ? 'top' : ''}`}
        style={{ width: `${probability * 100}%` }}
      />
    </div>
  );
}

function PredictionCard({ 
  prediction, 
  rank, 
  isTop 
}: { 
  prediction: { word: string; probability: number; explanation: string };
  rank: number;
  isTop: boolean;
}) {
  return (
    <div className={`prediction-card ${isTop ? 'top-prediction' : ''}`}>
      <div className="prediction-header">
        <span className="rank">#{rank}</span>
        <span className="word">"{prediction.word}"</span>
        <span className="probability">{(prediction.probability * 100).toFixed(1)}%</span>
      </div>
      <ProbabilityBar probability={prediction.probability} isTop={isTop} />
      <p className="explanation">{prediction.explanation}</p>
    </div>
  );
}

export default function App() {
  const [input, setInput] = useState('the capital of france is');

  const normalizedInput = input.toLowerCase().trim();
  const predictions = predictionDatabase[normalizedInput];

  const matchingExample = examplePhrases.find(phrase => 
    normalizedInput.startsWith(phrase.slice(0, 5))
  );

  return (
    <div className="app">
      <div className="header">
        <h1>LLM Word Predictor</h1>
        <p className="subtitle">
          See how AI predicts the next word based on patterns it learned
        </p>
      </div>

      <div className="input-section">
        <label htmlFor="phrase-input">Type a phrase:</label>
        <input
          id="phrase-input"
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Type a phrase..."
          className="phrase-input"
        />

        <div className="example-phrases">
          <span className="examples-label">Try these examples:</span>
          <div className="example-buttons">
            {examplePhrases.map((phrase) => (
              <button
                key={phrase}
                className={`example-btn ${normalizedInput === phrase ? 'active' : ''}`}
                onClick={() => setInput(phrase)}
              >
                {phrase}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="predictions-section">
        <h2>Predicted Next Words</h2>

        {predictions ? (
          <>
            <p className="predictions-intro">
              Based on the pattern "{input}", here's what an LLM might predict:
            </p>
            <div className="predictions-grid">
              {predictions.map((pred, index) => (
                <PredictionCard
                  key={pred.word}
                  prediction={pred}
                  rank={index + 1}
                  isTop={index === 0}
                />
              ))}
            </div>
          </>
        ) : (
          <div className="no-predictions">
            <p>Try one of the example phrases above to see predictions!</p>
            <p className="hint">
              Real LLMs can predict for any text, but this demo uses a small set of examples to illustrate the concept.
            </p>
          </div>
        )}
      </div>

      <div className="insight-box">
        <h3>How Real LLMs Do This</h3>
        <p>
          Real LLMs don't use a lookup table like this demo. Instead, they use <strong>billions of parameters</strong> to calculate probabilities for every possible next word based on patterns learned from massive amounts of text.
        </p>
        <p>
          <strong>Key insight:</strong> When predictions are highly confident (like 95%+), the model has seen this pattern many times. When probabilities are spread out, there's more uncertainty about what comes next.
        </p>
        <p>
          Notice how famous quotes or well-known facts have very high confidence? That's because the model has seen these exact patterns thousands of times in training data.
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

.app {
  max-width: 800px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 2rem;
}

h1 {
  color: white;
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.85);
  font-size: 1rem;
}

.input-section {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.input-section label {
  display: block;
  font-weight: 600;
  color: #1f2937;
  margin-bottom: 0.5rem;
}

.phrase-input {
  width: 100%;
  padding: 1rem;
  font-size: 1.1rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.75rem;
  margin-bottom: 1rem;
  transition: border-color 0.2s;
}

.phrase-input:focus {
  outline: none;
  border-color: #3b82f6;
}

.example-phrases {
  border-top: 1px solid #e5e7eb;
  padding-top: 1rem;
}

.examples-label {
  display: block;
  font-size: 0.85rem;
  color: #6b7280;
  margin-bottom: 0.5rem;
}

.example-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.example-btn {
  padding: 0.5rem 0.75rem;
  background: #f3f4f6;
  border: 1px solid #e5e7eb;
  border-radius: 0.5rem;
  font-size: 0.8rem;
  color: #4b5563;
  cursor: pointer;
  transition: all 0.2s;
}

.example-btn:hover {
  background: #e5e7eb;
}

.example-btn.active {
  background: #3b82f6;
  border-color: #3b82f6;
  color: white;
}

.predictions-section {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.predictions-section h2 {
  color: #1f2937;
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.predictions-intro {
  color: #6b7280;
  font-size: 0.9rem;
  margin-bottom: 1rem;
}

.predictions-grid {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.prediction-card {
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 0.75rem;
  padding: 1rem;
  transition: all 0.2s;
}

.prediction-card.top-prediction {
  background: #ecfdf5;
  border-color: #10b981;
}

.prediction-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.rank {
  font-size: 0.85rem;
  font-weight: 600;
  color: #6b7280;
}

.top-prediction .rank {
  color: #059669;
}

.word {
  font-size: 1.25rem;
  font-weight: 700;
  color: #1f2937;
  flex: 1;
}

.top-prediction .word {
  color: #047857;
}

.probability {
  font-size: 1.1rem;
  font-weight: 700;
  color: #3b82f6;
}

.top-prediction .probability {
  color: #059669;
}

.probability-bar {
  height: 8px;
  background: #e5e7eb;
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 0.75rem;
}

.probability-fill {
  height: 100%;
  background: #3b82f6;
  border-radius: 4px;
  transition: width 0.3s ease;
}

.probability-fill.top {
  background: #10b981;
}

.explanation {
  font-size: 0.85rem;
  color: #6b7280;
  line-height: 1.4;
}

.no-predictions {
  text-align: center;
  padding: 2rem;
  color: #6b7280;
}

.no-predictions .hint {
  font-size: 0.85rem;
  margin-top: 0.5rem;
  color: #9ca3af;
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.5rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.75rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .example-btn {
    font-size: 0.7rem;
    padding: 0.4rem 0.6rem;
  }
}
